const item = $('Gmail 수신 확인').first().json;

const from = item.from?.text || item.From || '';
const subject = item.subject || item.Subject || '(제목없음)';
const messageId = item.id || item.messageId || '';
const date = item.date || item.Date || new Date().toISOString();

// GitHub 알림 제외
if (from.includes('github.com') || from.includes('notifications@')) {
  return [];
}

// 본문 추출: item.text 우선 (전체 이메일 체인 포함), html에서 strip
let rawText = '';
if (item.text && item.text.length > 0) {
  rawText = item.text;
} else if (item.html) {
  rawText = item.html.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
} else if (item.snippet) {
  rawText = item.snippet;
}

// 첨부파일 힌트: html이 100KB 이상이면 인라인 첨부파일 있을 가능성
const htmlSize = (item.html || '').length;
const hasInlineAttachment = htmlSize > 100000;
const attachmentHint = hasInlineAttachment
  ? `\n\n> ⚠️ 대용량 메일 (HTML ${Math.round(htmlSize/1024)}KB) — PDF 등 첨부파일 포함 가능. 원본 메일 직접 확인 필요.`
  : '';

// 명시적 첨부파일 목록
const attachments = item.attachments || [];
const attachmentList = attachments.length > 0
  ? '\n\n**첨부파일**:\n' + attachments.map(a => `- ${a.filename || '파일'} (${a.contentType || a.mimeType || '?'})`).join('\n')
  : '';

// Ollama용: 원문 텍스트 앞 3000자 (전체 체인 포함)
const bodyForOllama = rawText.substring(0, 3000);

// v4: rawAttachments — Gmail API 첨부파일 ID 목록 추출
const rawAttachments = [];
for (const part of (item.payload?.parts || [])) {
  if (part.filename && part.filename.length > 0 && part.body?.attachmentId) {
    rawAttachments.push({
      filename: part.filename,
      mimeType: part.mimeType || 'application/octet-stream',
      attachmentId: part.body.attachmentId
    });
  }
}

return [{ json: { messageId, from, subject, date, bodyForOllama, attachmentHint, attachmentList, htmlSize, rawAttachments } }];

// Gmail OAuth2 자격증명으로 첨부파일 다운로드
const items = $input.all();
const results = [];

for (const item of items) {
  const parsed = item.json;
  const rawAttachments = parsed.rawAttachments || [];
  const messageId = parsed.messageId || '';
  const attachment_files = [];

  for (const att of rawAttachments) {
    if (!att.attachmentId) continue;
    try {
      const response = await $helpers.httpRequest({
        method: 'GET',
        url: `https://gmail.googleapis.com/gmail/v1/users/me/messages/${messageId}/attachments/${att.attachmentId}`,
        authentication: 'predefinedCredentialType',
        nodeCredentialType: 'gmailOAuth2',
      });
      if (response.data) {
        attachment_files.push({
          filename: att.filename,
          content_type: att.mimeType || 'application/octet-stream',
          data: response.data
        });
      }
    } catch (e) {
      // 첨부파일 다운로드 실패 시 skip (워크플로우 계속)
    }
  }

  results.push({
    json: { ...parsed, attachment_files }
  });
}

return results;

const mailData = $('메일 파싱').first().json;
const opData = $input.first().json;
const wpList = (opData._embedded?.elements || []).map(wp => `${wp.id}: ${wp.subject}`).join('\n');

const ollamaBody = JSON.stringify({
  model: 'llama3.2:3b',
  temperature: 0,
  messages: [
    {
      role: 'system',
      content: `You are an RA (Regulatory Affairs) task manager. Analyze the email and:
1. Find the most similar existing work package from the list (similarity >= 0.6)
2. Summarize the actual task being requested in Korean (ignore greetings, signatures, disclaimers, email footers)

Respond ONLY with valid JSON (no markdown, no code block):
{"matched_id": <number or null>, "matched_title": "<string>", "reason": "<one line in Korean>", "task_summary": "<2-3 sentences in Korean describing what task is requested>", "attachments_note": "<names of mentioned documents/files or empty string>"}`
    },
    {
      role: 'user',
      content: `Subject: ${mailData.subject}\nFrom: ${mailData.from}\n\nEmail body:\n${mailData.bodyForOllama}\n\nExisting Work Packages:\n${wpList}`
    }
  ]
});
return [{ json: { ...mailData, ollamaBody, wpList } }];

const mailData = $('메일 파싱').first().json;
const opData = $('OP 프로젝트 96 WP 조회').first().json;
const ollamaResp = $input.first().json;

let matchedId = null;
let matchedTitle = '';
let reason = '';
let taskSummary = '';
let attachmentsNote = '';

try {
  const content = ollamaResp?.choices?.[0]?.message?.content || '{}';
  // 마크다운 코드블록 제거
  const jsonStr = content.replace(/```json?/g, '').replace(/```/g, '').trim();
  const parsed = JSON.parse(jsonStr);
  matchedId = parsed.matched_id || null;
  matchedTitle = parsed.matched_title || '';
  reason = parsed.reason || '';
  taskSummary = parsed.task_summary || '';
  attachmentsNote = parsed.attachments_note || '';
} catch(e) {
  matchedId = null;
  taskSummary = '(AI 분석 실패 - 원본 메일 직접 확인)';
}

// v4: 첨부파일 다운로드 데이터 전달
const attachDownload = $('첨부파일 다운로드').first().json;
const attachment_files = attachDownload.attachment_files || [];

return [{ json: {
  ...mailData,
  attachment_files,
  matchedId,
  matchedTitle,
  reason,
  taskSummary,
  attachmentsNote,
  hasMatch: matchedId !== null,
} }];

const mailData = $('유사도 결과 파싱').first().json;
const hermesRaw = $input.first().json;

// Extract wp_comment from OpenAI-format response
let hermesData = {};
try {
  const contentStr = hermesRaw?.choices?.[0]?.message?.content || '';
  const clean = contentStr.replace(/```json?\s*/g, '').replace(/```/g, '').trim();
  const parsed = JSON.parse(clean);
  hermesData = parsed?.wp_comment || parsed;
} catch(e) {
  hermesData = {};
}

const emailType = hermesData.email_type || '액션필요';

// Use hermes wp_title, or generate from parts
function buildWpTitle(hermes, emailSubject, type) {
  if (hermes.wp_title && hermes.wp_title.length > 5) return hermes.wp_title;
  const prefix = type === '완료통보' ? '[완료]' : type === '정보수신' ? '[정보]' : '[액션]';
  const org = (hermes.org || '').trim();
  const product = (hermes.product || '').trim();
  const deadline = hermes.deadline ? ` [${hermes.deadline}]` : '';
  const target = org ? (product ? `${org}/${product}` : org) : '';
  if (target) return `${prefix} ${target}${deadline}`;
  return `${prefix} ${(emailSubject || '').substring(0, 50)}${deadline}`;
}

const wpTitle = buildWpTitle(hermesData, mailData.subject, emailType);

// Status: 1=Open, 12=Done, 15=Ticketed(reference)
const wpStatus = emailType === '완료통보' ? 12 : emailType === '정보수신' ? 15 : 1;

// Skip WP creation for 완료통보/정보수신 when a matching WP already exists
const skipWpCreation = (emailType !== '액션필요') && mailData.hasMatch;

const priorityLabel = { high: '높음 (즉시 대응)', medium: '보통', low: '낮음' }[hermesData.confidence] || '보통';

const parts = [
  `**발신**: ${mailData.from || ''}`,
  `**수신일**: ${mailData.date || ''}`,
  `**메일유형**: ${emailType}`,
];
if (hermesData.org) parts.push(`**발신기관**: ${hermesData.org}`);
if (hermesData.product) parts.push(`**제품**: ${hermesData.product}`);
if (hermesData.deadline) parts.push(`**기한**: ${hermesData.deadline}`);
parts.push(`**신뢰도**: ${priorityLabel}`);
parts.push('');
parts.push('## 업무 요약');
parts.push(hermesData.summary || mailData.taskSummary || '(원본 메일 확인 필요)');
parts.push('');
parts.push('## 필요 조치');
parts.push(hermesData.recommendation || '(RA 담당자 직접 확인 필요)');
if (mailData.attachmentList) parts.push(mailData.attachmentList);
if (mailData.attachmentHint) { parts.push(''); parts.push(mailData.attachmentHint); }
parts.push('');
parts.push('---');
parts.push('*[Hermes 자동등록]*');

const descRaw = parts.join('\n');
const matchNote = mailData.hasMatch
  ? `*유사업무: ${mailData.matchedTitle || ''} (#${mailData.matchedId || ''})*`
  : '*유사업무 없음 → 신규 등록*';

const baseWpLinks = {
  type: { href: '/api/v3/types/1' },
  assignee: { href: '/api/v3/users/6' },
  status: { href: `/api/v3/statuses/${wpStatus}` }
};

const rootBody = JSON.stringify({
  subject: wpTitle,
  description: { format: 'markdown', raw: descRaw + '\n' + matchNote },
  _links: baseWpLinks,
  ...(hermesData.deadline ? { dueDate: hermesData.deadline } : {})
});

const childBody = JSON.stringify({
  subject: wpTitle,
  description: { format: 'markdown', raw: descRaw + '\n' + matchNote },
  _links: { ...baseWpLinks, parent: { href: `/api/v3/work_packages/${mailData.matchedId}` } },
  ...(hermesData.deadline ? { dueDate: hermesData.deadline } : {})
});

return [{ json: { ...mailData, hermesData, wpTitle, wpSubject: wpTitle, emailType, wpStatus, skipWpCreation, rootBody, childBody } }];

const item = $input.first().json;
// OpenProject returns hal+json; n8n wraps it as {data: "...string..."}
const wpData = (() => {
  if (item.id) return item;
  try { return JSON.parse(item.data || '{}'); } catch(e) { return {}; }
})();
const mailData = $('유사도 결과 파싱').first().json;
const wpBodyData = $('WP 본문 생성').first().json;
return [{ json: {
  createdWpId: wpData.id,
  createdWpSubject: wpData.subject,
  messageId: mailData.messageId,
  mailSubject: mailData.subject,
  hasMatch: mailData.hasMatch,
  matchedId: mailData.matchedId,
  hermesData: wpBodyData.hermesData || {}
} }];

const data = $input.first().json;

// Skip comment posting if flagged (e.g. null matchedId path)
if (data._skip_comment) {
  return [{ json: { ...data, comment_body: '', commentBody: '', _skip_comment: true } }];
}

const hermesRaw = $('hermes 분석 API').first().json;

// Parse wp_comment from OpenAI-format response
let wpComment = null;
try {
  const contentStr = hermesRaw?.choices?.[0]?.message?.content || '';
  const clean = contentStr.replace(/```json?\s*/g, '').replace(/```/g, '').trim();
  const parsed = JSON.parse(clean);
  wpComment = parsed?.wp_comment || parsed;
} catch(e) {
  wpComment = null;
}

const nas_refs = (wpComment && wpComment.source_docs) || [];
const emailType = data.emailType || wpComment?.email_type || '액션필요';
const typeIcon = emailType === '완료통보' ? '✅' : emailType === '정보수신' ? 'ℹ️' : '⚡';

function formatSourceDocs(refs) {
  if (!refs || refs.length === 0) return '';
  return refs.map(r => {
    if (typeof r === 'object' && r.file) {
      const score = r.score ? ` (관련도: ${r.score})` : '';
      const excerpt = r.excerpt ? `\n  > ${r.excerpt.substring(0, 150).replace(/\n/g, ' ')}` : '';
      return `- **${r.file}**${score}${excerpt}`;
    }
    return `- ${r}`;
  }).join('\n');
}

let comment_body = '';
if (wpComment && wpComment.recommendation) {
  const h = wpComment;
  const confidenceIcon = { high: '🟢', medium: '🟡', low: '🔴' }[h.confidence] || '🟡';
  const confidenceLabel = { high: '높음', medium: '보통', low: '낮음' }[h.confidence] || '보통';

  let rows = `| 유형 | ${typeIcon} **${emailType}** |\n`;
  rows += `| 신뢰도 | ${confidenceIcon} **${confidenceLabel}** |\n`;
  if (h.deadline) rows += `| ⏰ 기한 | **${h.deadline}** |\n`;
  if (h.org) rows += `| 🏢 발신기관 | ${h.org} |\n`;
  if (h.product) rows += `| 📦 제품 | ${h.product} |\n`;

  let c = `## [Hermes] RA 대응 가이드\n\n`;
  c += `| 항목 | 내용 |\n|---|---|\n${rows}\n`;
  c += `### 권고 조치\n${h.recommendation}\n\n`;
  if (h.summary) c += `### 업무 요약\n${h.summary}\n\n`;

  const ma = h.market_analysis || {};
  const maItems = [];
  if (ma.mfds) maItems.push(`- **MFDS**: ${ma.mfds}`);
  if (ma.ce_mdr) maItems.push(`- **CE MDR**: ${ma.ce_mdr}`);
  if (ma.fda) maItems.push(`- **FDA**: ${ma.fda}`);
  if (maItems.length > 0) c += `### 시장 규제 분석\n${maItems.join('\n')}\n\n`;

  const nasFormatted = formatSourceDocs(nas_refs);
  if (nasFormatted) c += `### NAS 참고 문서 (RAG)\n${nasFormatted}\n\n`;

  c += `---\n*Hermes RA Agent 자동 분석 (3-layer RAG + GLM-4-Air)*`;
  comment_body = c;
} else {
  const h = data.hermesData || {};
  const confidenceIcon = { high: '🟢', medium: '🟡', low: '🔴' }[h.confidence] || '🟡';
  const confidenceLabel = { high: '높음', medium: '보통', low: '낮음' }[h.confidence] || '보통';

  let rows = `| 유형 | ${typeIcon} **${emailType}** |\n`;
  rows += `| 신뢰도 | ${confidenceIcon} **${confidenceLabel}** |\n`;
  if (h.deadline) rows += `| ⏰ 기한 | **${h.deadline}** |\n`;
  if (h.org) rows += `| 🏢 발신기관 | ${h.org} |\n`;

  let c = `## [Hermes] RA 대응 가이드\n\n`;
  c += `| 항목 | 내용 |\n|---|---|\n${rows}\n`;
  c += `### 권고 조치\n${h.recommendation || '(원본 메일 확인 후 조치 결정)'}\n\n`;
  if (h.summary) c += `### 업무 요약\n${h.summary}\n\n`;

  const nasFormatted = formatSourceDocs(nas_refs);
  if (nasFormatted) c += `### NAS 참고 문서 (RAG)\n${nasFormatted}\n\n`;

  c += `---\n*Hermes RA Agent 자동 분석 (fallback)*`;
  comment_body = c;
}

return [{ json: { ...data, comment_body, commentBody: JSON.stringify({ comment: { raw: comment_body } }) } }];

const data = $input.first().json;
// Route to existing matched WP — no new WP creation needed
// Guard: matchedId must be non-null; if null fall through without action
if (!data.matchedId) {
  return [{ json: {
    createdWpId: null,
    createdWpSubject: data.wpTitle || '',
    messageId: data.messageId,
    mailSubject: data.subject,
    hasMatch: false,
    matchedId: null,
    hermesData: data.hermesData,
    emailType: data.emailType,
    _skip_comment: true
  } }];
}
return [{ json: {
  createdWpId: data.matchedId,
  createdWpSubject: data.matchedTitle || data.wpTitle,
  messageId: data.messageId,
  mailSubject: data.subject,
  hasMatch: data.hasMatch,
  matchedId: data.matchedId,
  hermesData: data.hermesData,
  emailType: data.emailType
} }];

