// Runs once per model (3 times: Codex, GLM, Copilot)
// Use items[] (legacy API) for cross-version compatibility
const modelResponse = (items && items.length > 0) ? items[0].json : {};

// Skip if no input (model node failed)
if (!modelResponse || !modelResponse.choices) return [];

// Get WP ID from creation branch (completes before slow model analysis)
let createdWpId = null;
try {
  createdWpId = $('결과 통합').first().json.createdWpId;
} catch(e) {}

const modelText = modelResponse.choices[0]?.message?.content || '(응답 없음)';
const modelTokens = modelResponse.usage || {};
const rawModel = modelResponse.model || 'unknown';

return [{
  json: {
    createdWpId,
    modelResult: {
      model: rawModel,
      content: modelText,
      inputTokens: modelTokens.prompt_tokens || 0,
      outputTokens: modelTokens.completion_tokens || 0,
      totalTokens: modelTokens.total_tokens || 0
    }
  }
}];

const modelResponse = (items && items.length > 0) ? items[0].json : {};
const wpId = modelResponse.createdWpId;
const model = modelResponse.modelResult;

if (!wpId || !model || !model.content || model.content === '(응답 없음)') {
  return [];
}

const commentContent = `🤖 **${model.model} 분석 결과**\n\n${model.content}\n\n📊 토큰: 입력 ${model.inputTokens} / 출력 ${model.outputTokens} / 합계 ${model.totalTokens}`;

return [{
  json: {
    createdWpId: wpId,
    commentBody: JSON.stringify({ comment: { raw: commentContent } })
  }
}];

const data = $input.first().json;
// Route to existing matched WP — no new WP creation needed
return [{ json: {
  createdWpId: data.matchedId,
  createdWpSubject: data.matchedTitle || data.wpTitle,
  messageId: data.messageId,
  mailSubject: data.subject,
  hasMatch: data.hasMatch,
  matchedId: data.matchedId,
  hermesData: data.hermesData,
  emailType: data.emailType
} }];
